import { useState } from 'react';
import {
  JxPage,
  JxHeader,
  JxBadge,
  JxSection,
  JxDivider,
  JxSegmentedControl,
  JxSegmentedItem,
  JxSlider,
  JxSwitch,
  JxSelect,
  JxSelectItem,
  JxFieldRow,
  JxLabel,
  JxText,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'inter' | 'mono';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState<number>(100);
  const [dense, setDense] = useState<boolean>(false);
  const [font, setFont] = useState<Font>('system');

  const emit = (next: Partial<AppearanceSettings>) => {
    const settings: AppearanceSettings = {
      theme,
      scale,
      dense,
      font,
      ...next,
    };
    onChange?.(settings);
  };

  return (
    <JxPage>
      <JxHeader
        title="Внешний вид"
        right={<JxBadge tone="accent">{themeLabels[theme]}</JxBadge>}
      />

      <JxSection title="Тема оформления">
        <JxSegmentedControl
          value={theme}
          onChange={(value: string) => {
            const next = value as Theme;
            setTheme(next);
            emit({ theme: next });
          }}
        >
          <JxSegmentedItem value="light">Светлая</JxSegmentedItem>
          <JxSegmentedItem value="dark">Тёмная</JxSegmentedItem>
          <JxSegmentedItem value="system">Системная</JxSegmentedItem>
        </JxSegmentedControl>
      </JxSection>

      <JxSection title="Масштаб интерфейса">
        <JxFieldRow>
          <JxLabel>Масштаб</JxLabel>
          <JxText tone="muted">{scale}%</JxText>
        </JxFieldRow>
        <JxSlider
          min={80}
          max={140}
          step={5}
          value={scale}
          onChange={(value: number) => {
            setScale(value);
            emit({ scale: value });
          }}
        />
      </JxSection>

      <JxSection title="Плотность">
        <JxFieldRow>
          <JxLabel>Плотная вёрстка</JxLabel>
          <JxSwitch
            checked={dense}
            onChange={(checked: boolean) => {
              setDense(checked);
              emit({ dense: checked });
            }}
          />
        </JxFieldRow>
      </JxSection>

      <JxDivider />

      <JxSection title="Ещё">
        <JxFieldRow>
          <JxLabel>Шрифт</JxLabel>
          <JxSelect
            value={font}
            onChange={(value: string) => {
              const next = value as Font;
              setFont(next);
              emit({ font: next });
            }}
          >
            <JxSelectItem value="system">Системный</JxSelectItem>
            <JxSelectItem value="inter">Inter</JxSelectItem>
            <JxSelectItem value="mono">Моноширинный</JxSelectItem>
          </JxSelect>
        </JxFieldRow>
      </JxSection>
    </JxPage>
  );
}

